const mQ=s=>document.querySelector(s);
let materialUser,materialStudents=[],materialStudent=null,materialLesson=null,materialOffset=0,materialBusy=false,materialTotal=0;
const materialDrafts=new Map();
const mDate=(iso,tz)=>new Date(iso).toLocaleString('ru-RU',{timeZone:tz,dateStyle:'long',timeStyle:'short'});
const mDay=value=>{const [y,m,d]=String(value).slice(0,10).split('-');return [d,m,y].join('.')};
function mNode(tag,text,className){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e}
async function mApi(path,options={}){const response=await fetch('/api/'+path,{cache:'no-store',...options});const result=await response.json();if(!response.ok){const message=typeof result.detail==='string'?result.detail:Array.isArray(result.detail)?'Проверьте поля формы и срок задания.':'Не удалось выполнить запрос. Попробуйте ещё раз.';throw Error(message)}return result}
function mWrite(path,method,data){return mApi(path,{method,headers:{'Content-Type':'application/json','X-Requested-With':'KrugPi'},body:JSON.stringify(data)})}
function mDeadline(row){if(row.due_mode==='manual')return 'К дате: '+mDay(row.due_date);return row.next_lesson_at?'К следующему занятию: '+mDate(row.next_lesson_at,row.timezone):'К следующему занятию — дата пока не назначена'}
function mFreeze(value){materialBusy=value;document.querySelectorAll('#content button,#content input,#content select,#content textarea').forEach(e=>e.disabled=value);if(!value){mQ('#previous').disabled=materialOffset===0;mQ('#next').disabled=materialOffset+20>=materialTotal}}
async function mRefresh(){if(materialBusy)return;mFreeze(true);mQ('#status').textContent='Загружаем…';try{await mLoad();mQ('#status').textContent=''}catch(e){mQ('#lesson-materials').replaceChildren();mQ('#status').textContent=e.message}finally{mFreeze(false)}}
async function mLoad(){const params=new URLSearchParams({limit:20,offset:materialOffset});if(materialStudent)params.set('student_id',materialStudent);if(materialLesson)params.set('lesson_id',materialLesson);const result=await mApi('materials?'+params);materialTotal=result.total;mQ('#lesson-materials').replaceChildren(...result.items.map(mCard));mQ('#count').textContent='Уроков: '+result.total;mQ('#previous').disabled=materialOffset===0;mQ('#next').disabled=materialOffset+20>=result.total;if(!result.items.length)mQ('#lesson-materials').append(mNode('p',materialUser.role==='admin'?'Проведённых уроков пока нет. Сначала отметьте закончившийся урок как «Проведено» в расписании.':'Преподаватель пока не добавил материалы к проведённым урокам.','materials-empty'))}
async function mMutation(action,feedback,success){if(materialBusy)return false;mFreeze(true);feedback.textContent='Сохраняем…';let saved=false;try{await action();saved=true;feedback.textContent=success;try{await mLoad();mQ('#status').textContent=success}catch{mQ('#status').textContent=success+' Не удалось обновить список — нажмите «Обновить».'}return true}catch(e){feedback.textContent=e.message;return false}finally{mFreeze(false);if(saved){mQ('#previous').disabled=materialOffset===0}}}
function mCard(row){const card=mNode('article',undefined,'panel lesson-material');card.id='lesson-'+row.lesson_id;card.append(mNode('h2',row.topic||'Урок математики'),mNode('p',(materialUser.role==='admin'?row.student_name+' · ':'')+mDate(row.starts_at,row.timezone),'material-date'));if(row.updated_at)card.append(mNode('p','Материалы обновлены: '+mDate(new Date(row.updated_at*1000).toISOString(),row.timezone),'muted small'));const columns=mNode('div',undefined,'material-columns');
for(const [category,title,text] of [['homework','Домашнее задание',row.homework],['notes','Конспект урока',row.notes]]){const block=mNode('section',undefined,'material-block');block.append(mNode('h3',title),mNode('p',text||(category==='homework'?'Пока не добавлено.':'Пока не добавлен.'),'material-text'));const files=row.files.filter(f=>f.category===category);if(category==='homework'&&(text||files.length))block.append(mNode('p',mDeadline(row),'material-deadline'));const list=mNode('ul',undefined,'material-files');const feedback=mNode('p',undefined,'material-feedback');feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');for(const f of files){const li=mNode('li'),a=mNode('a',f.filename);a.href='/api/materials/files/'+encodeURIComponent(f.id);li.append(a,mNode('small',' · '+Math.ceil(f.size/1024)+' КБ'));if(materialUser.role==='admin'){const remove=mNode('button','Убрать');remove.type='button';remove.onclick=()=>{if(!confirm('Убрать вложение «'+f.filename+'» из материалов урока?'))return;void mMutation(()=>mApi('materials/files/'+f.id,{method:'DELETE',headers:{'X-Requested-With':'KrugPi'}}),feedback,'Вложение убрано.')};li.append(remove)}list.append(li)}block.append(list);
if(materialUser.role==='admin'){const form=mNode('form',undefined,'upload-form'),label=mNode('label','Прикрепить '+(category==='homework'?'задание':'конспект')),input=mNode('input');input.type='file';input.multiple=true;input.accept='.pdf,.jpg,.jpeg,.png';input.required=true;label.append(input);const upload=mNode('button','Загрузить файлы');upload.type='submit';form.append(label,mNode('p','PDF, JPG, PNG · до 5 файлов по 10 МБ в этом блоке','muted small'),upload);form.onsubmit=async e=>{e.preventDefault();if(input.files.length+files.length>5){feedback.textContent='Максимум 5 файлов в каждом блоке.';return}if([...input.files].some(f=>f.size>10*1024*1024)){feedback.textContent='Каждый файл должен быть не больше 10 МБ.';return}const body=new FormData();for(const f of input.files)body.append('files',f);await mMutation(()=>mApi('materials/'+row.lesson_id+'/files?category='+category,{method:'POST',headers:{'X-Requested-With':'KrugPi'},body}),feedback,'Файлы добавлены.')};block.append(form)}block.append(feedback);columns.append(block)}card.append(columns);
if(materialUser.role==='admin'){const draft=materialDrafts.get(row.lesson_id),editRow=draft||row;const details=mNode('details',undefined,'material-editor');details.open=!!draft;details.append(mNode('summary','Редактировать задание, конспект и срок'));const form=mNode('form'),fieldset=mNode('fieldset');const inputs={};for(const [name,label,value] of [['homework','Текст домашнего задания',editRow.homework],['notes','Текст конспекта',editRow.notes]]){const l=mNode('label',label),t=mNode('textarea');t.name=name;t.maxLength=20000;t.value=value;inputs[name]=t;l.append(t);fieldset.append(l)}const modeLabel=mNode('label','Срок домашнего задания'),mode=mNode('select');for(const [value,label] of [['next','К следующему занятию'],['manual','Указать дату вручную']]){const o=mNode('option',label);o.value=value;mode.append(o)}mode.value=editRow.due_mode;modeLabel.append(mode);const dateLabel=mNode('label','Дата выполнения'),date=mNode('input');date.type='date';date.value=editRow.due_date?String(editRow.due_date).slice(0,10):'';dateLabel.append(date);const sync=()=>{dateLabel.hidden=mode.value!=='manual';date.required=mode.value==='manual'};mode.onchange=sync;sync();const save=mNode('button','Сохранить текст и срок');save.type='submit';const feedback=mNode('p',undefined,'material-feedback');feedback.setAttribute('role','status');feedback.setAttribute('aria-live','polite');fieldset.append(modeLabel,dateLabel,save);form.append(fieldset,feedback);const payload=()=>({homework:inputs.homework.value,notes:inputs.notes.value,due_mode:mode.value,due_date:mode.value==='manual'?date.value:null,version:editRow.version});form.oninput=()=>materialDrafts.set(row.lesson_id,payload());form.onchange=()=>materialDrafts.set(row.lesson_id,payload());form.onsubmit=e=>{e.preventDefault();void mMutation(async()=>{await mWrite('materials/'+row.lesson_id,'PUT',payload());materialDrafts.delete(row.lesson_id)},feedback,'Текст и срок сохранены.')};details.append(form);card.append(details)}return card}
mQ('#refresh').onclick=()=>mRefresh();mQ('#previous').onclick=()=>{if(materialBusy)return;materialOffset=Math.max(0,materialOffset-20);void mRefresh()};mQ('#next').onclick=()=>{if(materialBusy)return;materialOffset+=20;void mRefresh()};mQ('#student-select').onchange=()=>{if(materialBusy)return;materialStudent=Number(mQ('#student-select').value);materialOffset=0;materialLesson=null;const u=new URL(window.location.href);u.searchParams.set('student_id',materialStudent);u.searchParams.delete('lesson_id');history.replaceState(null,'',u);mQ('#show-all').hidden=true;void mRefresh()};
(async()=>{try{materialUser=await mApi('auth/me');if(materialUser.must_change_password){mQ('#status').textContent='Сначала смените временный пароль в личном кабинете.';return}const params=new URLSearchParams(location.search),source=params.get('lesson_id');if(source!==null){if(!/^[1-9][0-9]*$/.test(source)){mQ('#status').textContent='Некорректная ссылка на урок.';return}materialLesson=Number(source);mQ('#show-all').hidden=false}if(materialUser.role==='admin'){mQ('#back').href='admin.html?section=students';mQ('#student-picker').hidden=false;let offset=0,total;do{const page=await mApi('admin/students?limit=100&offset='+offset);materialStudents.push(...page.items);total=page.total;offset+=100}while(offset<total);const requested=params.get('student_id');if(requested!==null&&(!/^[1-9][0-9]*$/.test(requested)||!materialStudents.some(s=>s.id===Number(requested)))){mQ('#status').textContent='Ученик из ссылки не найден.';return}materialStudent=requested?Number(requested):materialLesson?null:materialStudents[0]?.id||null;const all=mNode('option','Все ученики');all.value='';mQ('#student-select').append(all);for(const s of materialStudents){const o=mNode('option',s.name+' ('+s.username+')');o.value=s.id;mQ('#student-select').append(o)}mQ('#student-select').value=String(materialStudent??'')}else materialStudent=materialUser.id;mQ('#show-all').href='materials.html'+(materialStudent?'?student_id='+materialStudent:'');mQ('#content').hidden=false;await mRefresh()}catch(e){mQ('#status').textContent=e.message}})();
